// AI 教练主界面的会话展示辅助（列表栏与顶部标题共用）
//
// 这里只放「纯展示」逻辑：标题降级文案、场景名解析、关联对象跳转目标、时间格式化。
// 数据来源仍然只有 apis/ai-conversation.ts 一处，
// 抽出来是为了避免列表栏与其它渲染位置各写一份、日后展示规则漂移。

import { formatDate } from "@/util/tips";
import { formatConversationTime, parseTimeString } from "@/util/time";
import { handleGotoJudgeJob, handleGotoProblem } from "@/util/router.ts";
import type { AiConversationItem, AiSceneMeta } from "@/apis/ai-conversation.ts";

/** 会话标题：后端 title 为空时给一个中性占位（不猜内容） */
export function GetConversationTitle(item: AiConversationItem): string {
  return item.title?.trim() || "未命名对话";
}

/** 场景展示名：以 /ai/scene 的服务端文案为准，取不到时回退场景 key（不硬编码中文映射） */
export function GetConversationSceneTitle(sceneList: AiSceneMeta[], scene: string): string {
  return sceneList.find((meta) => meta.key === scene)?.title ?? scene;
}

/** 关联对象文案：judge → 提交、problem → 题目、contest → 比赛；无关联对象返回空串 */
export function GetConversationRefLabel(item: AiConversationItem): string {
  if (!item.ref_type || item.ref_id <= 0) {
    return "";
  }
  if (item.ref_type === "judge") {
    return `提交 ${item.ref_id}`;
  }
  if (item.ref_type === "problem") {
    // 有 key 时显示 key（与题目详情页的地址一致），没有则退回内部 id（只展示、不跳转）
    const problemKey = GetConversationProblemKey(item);
    return problemKey ? `题目 ${problemKey}` : `题目 ${item.ref_id}`;
  }
  if (item.ref_type === "contest") {
    return `比赛 ${item.ref_id}`;
  }
  return `${item.ref_type} ${item.ref_id}`;
}

/** 题目引用的题目编号（key）：后端补了就用，没有就是空串 */
export function GetConversationProblemKey(item: AiConversationItem): string {
  return (item.problem_key ?? "").trim();
}

/**
 * 只有提交与题目有可跳转的页面（比赛等其他类型只展示文案，不做跳转）。
 *
 * 题目详情页按 key 查询（/problem/{key}），而会话表只存题目内部 id：
 * 拿不到 key 时不能拿 id 拼链接——那种地址后端不认，点开只会 404，
 * 因此判定为不可跳转，由调用方按纯文本 + GetConversationRefHint 展示。
 */
export function CanOpenConversationRef(item: AiConversationItem): boolean {
  if (item.ref_type === "judge") {
    return item.ref_id > 0;
  }
  if (item.ref_type === "problem") {
    return GetConversationProblemKey(item) !== "";
  }
  return false;
}

/** 关联对象不可跳转时的说明（无说明返回空串）；用于列表页的 title 与移动端卡片附注 */
export function GetConversationRefHint(item: AiConversationItem): string {
  if (item.ref_type === "problem" && item.ref_id > 0 && GetConversationProblemKey(item) === "") {
    return "该会话只记录了题目内部 id，题目页需要题目编号（key），暂无法跳转";
  }
  return "";
}

/** 跳转到会话关联的对象（不可跳转时不做任何事，避免跳到后端不认的地址） */
export async function OpenConversationRef(item: AiConversationItem) {
  if (!CanOpenConversationRef(item)) {
    return;
  }
  if (item.ref_type === "judge") {
    await handleGotoJudgeJob(String(item.ref_id));
    return;
  }
  if (item.ref_type === "problem") {
    await handleGotoProblem(GetConversationProblemKey(item));
  }
}

/** 列表里的更新时间：当天 HH:MM / 7 天内周X / 同年 MM-DD（与私信会话列表同一套格式化） */
export function GetConversationTimeText(item: AiConversationItem): string {
  const time = parseTimeString(item.modify_time);
  return time ? formatConversationTime(time) : (item.modify_time ?? "");
}

/** 完整时间（列表里做 title 悬浮提示用）：创建 / 更新时间 */
export function GetConversationFullTimeText(item: AiConversationItem, field: "insert_time" | "modify_time"): string {
  const raw = item[field];
  const time = parseTimeString(raw);
  return time ? formatDate(time) : (raw ?? "");
}
