<script setup lang="ts">
// AI 教练主界面（设计文档 §8 / 计划 Task C2 与决策记录 U1）
//
// 定位：这里是**完整的教练功能**——左侧会话列表（游标分页 / 新建 / 重命名 / 删除），
// 右侧对话区（直接对话、切换会话）。浮窗只是快捷入口，两者渲染的是同一套对话区组件
// （components/ai/AiChatView.vue）与同一份 store 状态，所以切换渲染位置不丢对话、也不新建会话。
//
// 路由：/ai/conversation（未选中会话）与 /ai/conversation/:id（选中某条会话，规范地址）都指向本组件，
// 进入时按 :id 选中会话；旧版的 /ai/conversation?id= 仍可用，选中后会把地址收敛成 :id 形式。
// 选中状态会同步回地址栏（点条目 / 新建 / 删除 / 新会话在服务端建好时），靠的是本页在 view-config
// 里声明的 viewKey：App.vue 据此把这两条路由当同一个页面渲染，写地址不会重建组件、也不闪加载条。
//
// 数据：会话列表 GET /ai/conversation/list 由后端按 modify_time 倒序做游标分页
// （AiConversationPage{ list, has_more, next_cursor_time, next_cursor_id }），
// 因此用「加载更多」逐页追加，不做全量拉取；会话详情与消息一律走 store（不在这里存第二份）。
//
// 响应式：桌面端左右两栏常驻；窄屏单栏切换（列表 ↔ 对话），断点复用 useBreakpoint，
// 两侧渲染的是同一批处理函数与同一个 store，业务逻辑只有一份。

import { computed, nextTick, onMounted, ref, watch } from "vue";
import { useRoute, useRouter } from "vue-router";
import { useCurrentInstance } from "@/util";
import { ShowErrorTips, ShowTextTipsSuccess, ShowTextTipsWarn } from "@/util/tips";
import { useBreakpoint } from "@/composables/useBreakpoint";
import { ResolveAiErrorText, useAiCoachStore } from "@/stores/aiCoach.ts";
import { GetAiConversationList, PostAiConversationDelete, PostAiConversationRename } from "@/apis/ai-conversation.ts";
import {
  CanOpenConversationRef,
  GetConversationFullTimeText,
  GetConversationRefHint,
  GetConversationRefLabel,
  GetConversationSceneTitle,
  GetConversationTimeText,
  GetConversationTitle,
  OpenConversationRef,
} from "@/views/ai/ai-conversation-display.ts";
import type { AiConversationItem, AiConversationPage } from "@/apis/ai-conversation.ts";
import AiChatView from "@/components/ai/AiChatView.vue";

const route = useRoute();
const router = useRouter();
const { globalProperties } = useCurrentInstance();
const { isMobile } = useBreakpoint();
// 会话与消息状态只存在 store 里：右侧对话区、浮窗读的都是它，本组件不复制任何会话数据
const store = useAiCoachStore();

/** 每页条数：与后端 aiChatConversationDefaultLimit 一致（后端还有上限，由后端收敛） */
const PAGE_SIZE = 20;

/** 对话区实例：新建对话后把焦点交给它的输入框 */
const chatRef = ref<InstanceType<typeof AiChatView> | null>(null);

/** 窄屏单栏：列表 ↔ 对话（桌面端两栏常驻，该值不生效） */
const mobilePane = ref<"list" | "chat">("list");

/** 是否已经在主界面开了新对话：conversationId 为 0 时用于区分「空态」与「正在新对话」 */
const started = ref(false);

// ── 路由选中 ──

/** 统一把 param / query 里的原始值收敛成正整数 id（非法一律当 0） */
function NormalizeId(raw: unknown): number {
  const text = Array.isArray(raw) ? raw[0] : raw;
  const id = Number(text);
  return Number.isInteger(id) && id > 0 ? id : 0;
}

/** 路由指定的会话 id：:id（/ai/conversation/:id，可能是数组）优先，其次 ?id=（旧版链接） */
const routeId = computed(() => NormalizeId(route.params.id) || NormalizeId(route.query.id));

/** 地址栏是否已是该会话的规范形式：选中会话用 /ai/conversation/:id，未选中用 /ai/conversation（?id= 旧链接不算） */
function isCanonicalRoute(id: number): boolean {
  if (id > 0) {
    return route.name === "ai-conversation-detail" && NormalizeId(route.params.id) === id;
  }
  // 未选中：路由名对还不够，旧版 ?id= 残留也要清掉（否则新建对话后地址仍挂着 ?id=）
  return route.name === "ai-conversation" && NormalizeId(route.query.id) <= 0;
}

/**
 * 把当前选中的会话同步到地址栏（见文件头：本页有 viewKey，写地址不会重建组件）。
 * 用 replace 而非 push：在左侧列表里来回点会话属于「同一页内改选中」，不该把历史记录塞满、
 * 让用户要按很多次返回才能离开本页；直接进 /ai/conversation/:id（浮窗跳转、外部链接）仍是 push。
 */
function syncRouteId(id: number) {
  if (isCanonicalRoute(id)) {
    return;
  }
  if (id > 0) {
    void router.replace({ name: "ai-conversation-detail", params: { id: String(id) } });
  } else {
    void router.replace({ name: "ai-conversation" });
  }
}

/**
 * 按路由选中会话：
 * - 路由没有 id 时什么都不做——从浮窗切过来要接着原来的会话聊，绝不能顺手 reset（那就成了新建会话）；
 * - 已是当前会话时跳过，避免重复拉取、也避免打断正在生成的那一轮；
 * - openPanel: false —— 主界面自己渲染对话区，不需要顺手把浮窗也打开（否则同一会话被渲染两次，
 *   移动端更糟：整屏抽屉会直接盖住主界面）。
 */
async function applyRouteSelection() {
  const id = routeId.value;
  if (id <= 0 || id === store.conversationId) {
    return;
  }
  if (store.generating) {
    ShowTextTipsWarn(globalProperties, "AI 正在生成中，请先停止或等本轮结束后再切换会话");
    return;
  }
  await store.loadConversation(id, { openPanel: false });
  started.value = true;
  mobilePane.value = "chat";
}

// ── 列表数据（游标分页）──

const items = ref<AiConversationItem[]>([]);
/** 首屏 / 重试 / 刷新 */
const loading = ref(false);
/** 加载更多（与首屏区分，避免整页 loading 遮住已有内容） */
const loadingMore = ref(false);
/** 是否已完成过一次加载：区分「还没加载」与「确实没有会话」 */
const loaded = ref(false);
const hasMore = ref(false);
const errorCode = ref(0);
const errorMessage = ref("");

// 下一页游标：由后端在 has_more 时回传，缺失即代表没有下一页
let cursorTime = "";
let cursorId = 0;

/** 应用后端回传的下一页游标：只有 has_more 且带回 cursor_time 才算还有下一页 */
function applyCursor(page: AiConversationPage | undefined) {
  cursorTime = page?.next_cursor_time ?? "";
  cursorId = page?.next_cursor_id ?? 0;
  hasMore.value = page?.has_more === true && !!cursorTime;
}

/** 重置列表状态（首屏加载与重试共用） */
async function loadFirstPage() {
  loading.value = true;
  errorCode.value = 0;
  errorMessage.value = "";
  hasMore.value = false;
  cursorTime = "";
  cursorId = 0;
  try {
    const res = await GetAiConversationList({ limit: PAGE_SIZE });
    if (res.code !== 0) {
      items.value = [];
      errorCode.value = res.code;
      errorMessage.value = ResolveAiErrorText("载入会话列表失败，请稍后重试", res.code);
      return;
    }
    const page = res.data as AiConversationPage;
    items.value = page?.list ?? [];
    applyCursor(page);
    loaded.value = true;
  } catch (e) {
    console.error("load ai conversation list failed:", e);
    items.value = [];
    errorCode.value = 0;
    errorMessage.value = "载入会话列表失败，请稍后重试";
  } finally {
    loading.value = false;
  }
}

/** 加载更多：带上后端回传的 cursor_time + cursor_id，追加下一页 */
async function loadMore() {
  if (loadingMore.value || loading.value || !hasMore.value || !cursorTime) {
    return;
  }
  loadingMore.value = true;
  try {
    const res = await GetAiConversationList({
      cursor_time: cursorTime,
      cursor_id: cursorId,
      limit: PAGE_SIZE,
    });
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    const page = res.data as AiConversationPage;
    // 游标分页的边界（同一 modify_time 的多条会话、期间有新会话写入）可能返回重复行，按 id 去重
    const exists = new Set(items.value.map((item) => item.id));
    (page?.list ?? []).forEach((item) => {
      if (!exists.has(item.id)) {
        exists.add(item.id);
        items.value.push(item);
      }
    });
    applyCursor(page);
  } catch (e) {
    console.error("load more ai conversation failed:", e);
    ShowTextTipsWarn(globalProperties, "加载更多失败，请稍后重试");
  } finally {
    loadingMore.value = false;
  }
}

// ── 选中与新建 ──

/**
 * 点列表项：切换右栏会话，并把选中结果写回地址栏（/ai/conversation/:id）。
 * 与浮窗共用 store.loadConversation（消息映射、场景元信息刷新都只有一份实现），
 * 只是不打开浮窗（见 applyRouteSelection 的说明）。
 * 先载入成功再改地址：地址一变 routeId 就会触发 applyRouteSelection，
 * 此时 store 里已是目标会话，那次判定会直接跳过，不会重复拉取。
 */
async function handleSelect(item: AiConversationItem) {
  mobilePane.value = "chat";
  if (item.id === store.conversationId) {
    // 已经是当前会话：只把地址补成规范形式（例如从浮窗进来时地址还没带 id）
    syncRouteId(item.id);
    return;
  }
  if (store.generating) {
    ShowTextTipsWarn(globalProperties, "AI 正在生成中，请先停止或等本轮结束后再切换会话");
    return;
  }
  started.value = true;
  await store.loadConversation(item.id, { openPanel: false });
  // 载入失败（如会话不存在）时 store 不会切过去：地址保持不动，避免地址栏指向一个打不开的会话
  if (store.conversationId === item.id) {
    syncRouteId(item.id);
  }
}

/** 新建对话：保留场景与引用，清空消息（浮窗同样会跟着清空，因为状态只有一份） */
async function handleNewConversation() {
  store.reset();
  started.value = true;
  mobilePane.value = "chat";
  // 新会话还没有服务端 id：地址回落到 /ai/conversation（发出第一条消息拿到 id 后再补上）
  syncRouteId(0);
  await nextTick();
  void chatRef.value?.focusInput();
}

/** 右侧标题：优先用列表里那条会话的标题（重命名后就地更新），找不到时给中性文案 */
const currentConversation = computed<AiConversationItem | null>(() => {
  const id = store.conversationId;
  if (id <= 0) {
    return null;
  }
  return items.value.find((item) => item.id === id) ?? store.conversations.find((item) => item.id === id) ?? null;
});

const chatTitle = computed(() => {
  if (currentConversation.value) {
    return GetConversationTitle(currentConversation.value);
  }
  return store.conversationId > 0 ? "当前对话" : "新对话";
});

/** 是否已经进入对话：没有选中会话、也没开新对话时右栏展示空态引导 */
const hasChat = computed(() => started.value || store.conversationId > 0 || store.messages.length > 0);

// ── 重命名 ──

const renameVisible = ref(false);
const renameTitle = ref("");
const renaming = ref(false);
let renameTargetId = 0;

function handleOpenRename(item: AiConversationItem) {
  renameTargetId = item.id;
  renameTitle.value = item.title ?? "";
  renameVisible.value = true;
}

async function handleSubmitRename() {
  const title = renameTitle.value.trim();
  if (!title) {
    ShowTextTipsWarn(globalProperties, "标题不能为空");
    return;
  }
  renaming.value = true;
  try {
    const res = await PostAiConversationRename(renameTargetId, title);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    // 就地更新：重命名不改 modify_time，列表顺序不变，无需整页重载
    const target = items.value.find((item) => item.id === renameTargetId);
    if (target) {
      target.title = title;
    }
    const current = store.conversations.find((item) => item.id === renameTargetId);
    if (current) {
      current.title = title;
    }
    renameVisible.value = false;
    ShowTextTipsSuccess(globalProperties, "已重命名");
  } catch (e) {
    console.error("rename ai conversation failed:", e);
    ShowTextTipsWarn(globalProperties, "重命名失败，请稍后重试");
  } finally {
    renaming.value = false;
  }
}

// ── 删除（二次确认）──

const deleteVisible = ref(false);
const deleting = ref(false);
const deleteTarget = ref<AiConversationItem | null>(null);

function handleOpenDelete(item: AiConversationItem) {
  deleteTarget.value = item;
  deleteVisible.value = true;
}

async function handleSubmitDelete() {
  const target = deleteTarget.value;
  if (!target) {
    return;
  }
  deleting.value = true;
  try {
    const res = await PostAiConversationDelete(target.id);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    items.value = items.value.filter((item) => item.id !== target.id);
    store.conversations = store.conversations.filter((item) => item.id !== target.id);
    // 删掉的正是当前对话：清空对话区（浮窗读同一份状态，也会一起复位），并收回空态
    if (store.conversationId === target.id) {
      store.reset();
      store.close();
      started.value = false;
      mobilePane.value = "list";
      // 会话已不存在：地址不能继续停在 /ai/conversation/:id 上
      syncRouteId(0);
    }
    deleteVisible.value = false;
    ShowTextTipsSuccess(globalProperties, "已删除会话");
  } catch (e) {
    console.error("delete ai conversation failed:", e);
    ShowTextTipsWarn(globalProperties, "删除失败，请稍后重试");
  } finally {
    deleting.value = false;
  }
}

onMounted(async () => {
  // 场景元信息与会话列表并行加载：场景名由 /ai/scene 提供（与浮窗共用 store 的缓存），
  // 晚到时列表里的场景标签会自动从场景 key 变为中文名
  void store.refreshSceneMeta();
  void loadFirstPage();
  await applyRouteSelection();
  // 兼容旧版 /ai/conversation?id=<id> 链接：确认选中后把地址收敛成规范形式 /ai/conversation/:id；
  // 载入失败（如会话不存在）时保留原地址，用户能看到自己点的到底是哪个 id
  const legacyId = NormalizeId(route.query.id);
  if (NormalizeId(route.params.id) <= 0 && legacyId > 0 && store.conversationId === legacyId) {
    syncRouteId(legacyId);
  }
  if (routeId.value > 0) {
    mobilePane.value = "chat";
  }
});

// 路由参数变化时重新选中（viewKey 让本页在两条会话路由间复用，不再重建组件，因此这里必须兜住；
// 反向的「选中 → 地址」同步在 handleSelect / handleNewConversation 等处显式调用）
watch(routeId, () => {
  void applyRouteSelection();
});

// 地址跟随当前会话：新会话在服务端建好后（发出第一条消息时才有 id）补上 /ai/conversation/:id；
// 会话被复位（新建 / 删除 / 浮窗「新对话」）时回落到 /ai/conversation，避免地址指向已不在展示的会话。
// 顺带刷新列表，让新会话出现在「我的对话」里；已在列表里的会话不受影响，不会因为切会话就整页重载
watch(
  () => store.conversationId,
  (id) => {
    syncRouteId(id);
    if (id > 0 && loaded.value && !items.value.some((item) => item.id === id)) {
      void loadFirstPage();
    }
  },
);
</script>

<template>
  <div class="ai-conv-page">
    <!-- 左栏：会话列表（桌面端常驻；窄屏只在「列表」页签下渲染） -->
    <aside v-if="!isMobile || mobilePane === 'list'" class="ai-conv-side">
      <div class="ai-conv-side-head">
        <span class="ai-conv-side-title">我的对话</span>
        <div class="ai-conv-side-actions">
          <t-button size="small" theme="primary" variant="text" @click="handleNewConversation">
            <template #icon><t-icon name="add" /></template>
            新建
          </t-button>
          <t-button size="small" variant="text" title="刷新" :loading="loading" @click="loadFirstPage">
            <template #icon><t-icon name="refresh" /></template>
          </t-button>
        </div>
      </div>

      <!-- 错误态：错误码经 GetText 出中文；原始码一并显示，便于报障时定位 -->
      <div v-if="errorMessage" class="ai-conv-error">
        <t-alert theme="error" :message="errorMessage" />
        <div class="ai-conv-error-footer">
          <span v-if="errorCode > 0" class="ai-conv-muted">错误码 {{ errorCode }}</span>
          <t-button size="small" theme="primary" variant="outline" @click="loadFirstPage">重试</t-button>
        </div>
      </div>

      <t-loading v-else class="ai-conv-side-body" :loading="loading" size="small" show-overlay text="加载中...">
        <div v-if="loaded && items.length === 0" class="ai-conv-side-empty">
          <t-empty description="还没有会话，新建一条开始对话" size="small" />
        </div>

        <!-- 会话条目：桌面端与窄屏同一套渲染（列表栏很窄，放不下多列表格） -->
        <div v-else class="ai-conv-items">
          <div
            v-for="item in items"
            :key="item.id"
            class="ai-conv-item"
            :class="{ 'is-active': item.id === store.conversationId }"
            :title="GetConversationFullTimeText(item, 'modify_time')"
            @click="handleSelect(item)"
          >
            <div class="ai-conv-item-top">
              <span class="ai-conv-item-title">{{ GetConversationTitle(item) }}</span>
              <span class="ai-conv-item-time">{{ GetConversationTimeText(item) }}</span>
            </div>
            <div class="ai-conv-item-tags">
              <t-tag size="small" variant="light">{{ GetConversationSceneTitle(store.sceneList, item.scene) }}</t-tag>
              <span
                v-if="GetConversationRefLabel(item)"
                class="ai-conv-item-ref"
                :class="{ 'is-link': CanOpenConversationRef(item) }"
                :title="GetConversationRefHint(item)"
                @click.stop="OpenConversationRef(item)"
              >
                {{ GetConversationRefLabel(item) }}
              </span>
            </div>
            <!-- 不可跳转时的说明（题目引用拿不到 key）：纯文本展示，不生成后端不认的链接 -->
            <div v-if="GetConversationRefHint(item)" class="ai-conv-item-ref-hint">{{ GetConversationRefHint(item) }}</div>
            <div class="ai-conv-item-foot">
              <span class="ai-conv-muted">{{ item.message_count }} 条消息 · {{ item.total_tokens }} tokens</span>
              <div class="ai-conv-item-actions" @click.stop>
                <t-button size="small" variant="text" @click="handleOpenRename(item)">重命名</t-button>
                <t-button size="small" theme="danger" variant="text" @click="handleOpenDelete(item)">删除</t-button>
              </div>
            </div>
          </div>
        </div>
      </t-loading>

      <!-- 加载更多：按后端游标逐页追加，不做全量拉取 -->
      <div v-if="items.length > 0" class="ai-conv-more">
        <t-button v-if="hasMore" size="small" theme="default" variant="outline" :loading="loadingMore" @click="loadMore">
          加载更多
        </t-button>
        <span v-else class="ai-conv-muted">已显示全部会话</span>
      </div>
    </aside>

    <!-- 右栏：对话区（与浮窗同一个 AiChatView、同一份 store 状态） -->
    <section v-if="!isMobile || mobilePane === 'chat'" class="ai-conv-main">
      <div class="ai-conv-main-head">
        <t-button
          v-if="isMobile"
          theme="default"
          variant="text"
          shape="square"
          title="返回会话列表"
          @click="mobilePane = 'list'"
        >
          <template #icon><t-icon name="chevron-left" /></template>
        </t-button>
        <div class="ai-conv-main-title" :title="chatTitle">
          <t-icon name="chat" />
          <span class="ai-conv-main-title-text">{{ chatTitle }}</span>
          <t-tag v-if="currentConversation" size="small" variant="light">
            {{ GetConversationSceneTitle(store.sceneList, currentConversation.scene) }}
          </t-tag>
        </div>
        <t-button size="small" theme="primary" variant="outline" @click="handleNewConversation">
          <template #icon><t-icon name="add" /></template>
          新建对话
        </t-button>
      </div>

      <!-- 对话区：会话/消息/草稿全在 store，浮窗与这里渲染的是同一条会话 -->
      <AiChatView v-if="hasChat" ref="chatRef" variant="page" />

      <!-- 空态：还没选中会话时给出出口（桌面端左栏常驻，窄屏可切回列表） -->
      <div v-else class="ai-conv-blank">
        <t-empty description="还没有选中会话" />
        <div class="ai-conv-blank-actions">
